$pixelScript = @'
const fs = require('fs');
const { PNG } = require('pngjs');
const pixelmatch = require('pixelmatch');
const reference = PNG.sync.read(fs.readFileSync('e2e/home-v2/fixtures/navbar-reference.png'));
const candidate = PNG.sync.read(fs.readFileSync('e2e/artifacts/task2468-navbar-visual/navbar-visual-1920.png'));
const width = reference.width, height = reference.height;
if (width !== candidate.width || height !== candidate.height) throw new Error('dimension mismatch');
const boxes = [[494,24,38,34],[634,24,38,34],[750,24,38,34],[871,24,38,34],[997,24,38,34],[1127,24,38,34],[1256,24,38,34],[1385,24,38,34],[1516,24,38,34],[1640,24,38,34],[1688,38,28,34],[1855,22,36,36]];
const refData = Buffer.from(reference.data), candidateData = Buffer.from(candidate.data), masked = new Uint8Array(width * height);
for (const [x0,y0,boxWidth,boxHeight] of boxes) for (let y=Math.max(0,y0); y<Math.min(height,y0+boxHeight); y++) for (let x=Math.max(0,x0); x<Math.min(width,x0+boxWidth); x++) { const p=y*width+x, i=p*4; masked[p]=1; refData[i]=refData[i+1]=refData[i+2]=refData[i+3]=0; candidateData[i]=candidateData[i+1]=candidateData[i+2]=candidateData[i+3]=0; }
let maskedPixels=0; for (const value of masked) maskedPixels+=value;
const total=width*height, allDiff=pixelmatch(reference.data,candidate.data,Buffer.alloc(total*4),width,height,{threshold:0.1,includeAA:false}), otherDiff=pixelmatch(refData,candidateData,Buffer.alloc(total*4),width,height,{threshold:0.1,includeAA:false});
console.log(JSON.stringify({overallSimilarity:((1-allDiff/total)*100).toFixed(3)+'%',iconBoxesMasked:maskedPixels,nonIconSimilarity:((1-otherDiff/(total-maskedPixels))*100).toFixed(3)+'%'},null,2));
'@; node -e $pixelScript
